import{_ as t,o,c as i,a5 as r}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"同时使用 v-if 和 v-for","description":"在 Vue 中，如果在同一个元素上同时使用 v if 和 v for ，会有优先级问题。Vue 的不同版本对此处理略有不同。 Vue 2 中的优先级 在 Vue 2 中， v for 的优先级高于 v if 。这意味着 v for 会首先被解析，然后在每个循环的过程中应用 v i。","frontmatter":{"title":"同时使用 v-if 和 v-for","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在 Vue 中，如果在同一个元素上同时使用 v if 和 v for ，会有优先级问题。Vue 的不同版本对此处理略有不同。 Vue 2 中的优先级 在 Vue 2 中， v for 的优先级高于 v if 。这意味着 v for 会首先被解析，然后在每个循环的过程中应用 v i。","sidebarWeight":41,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/同时使用 `v-if` 和 `v-for.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/同时使用 v-if 和 v-for.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/同时使用 v-if 和 v-for.md"}'),d={name:"posts/Vue系统教程/02-模板、组件与交互/同时使用 v-if 和 v-for.md"};function f(c,e,l,v,a,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<div><h1 id="同时使用-v-if-和-v-for" tabindex="-1">同时使用 v-if 和 v-for <a class="header-anchor" href="#同时使用-v-if-和-v-for" aria-label="Permalink to &quot;同时使用 v-if 和 v-for&quot;">​</a></h1><blockquote><p>本节目标：理解“同时使用 v-if 和 v-for”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 中，如果在同一个元素上同时使用 <code>v-if</code> 和 <code>v-for</code>，会有优先级问题。Vue 的不同版本对此处理略有不同。</p></blockquote><p>Vue 2 中的优先级 在 Vue 2 中，<code>v-for</code> 的优先级高于 <code>v-if</code>。这意味着 <code>v-for</code> 会首先被解析，然后在每个循环的过程中应用 <code>v-if</code>。 &lt;template&gt; &lt;ul&gt; &lt;li v-for=&quot;item in items&quot; v-if=&quot;item.isActive&quot; :key=&quot;item.id&quot;&gt; {{ item.name }} &lt;/li&gt; &lt;/ul&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { items: [ { id: 1, name: &#39;Item 1&#39;, isActive: true }, { id: 2, name: &#39;Item 2&#39;, isActive: false }, // 更多项... ] }; } }; &lt;/script&gt; 在这个例子中，<code>v-for</code> 会遍历 <code>items</code> 数组，然后在每个 <code>li</code> 元素上应用 <code>v-if</code> 判断。</p><p>Vue 3 中的优先级 在 Vue 3 中，这种优先级没有改变，仍然是 <code>v-for</code> 优先于 <code>v-if</code>。 &lt;template&gt; &lt;ul&gt; &lt;li v-for=&quot;item in items&quot; v-if=&quot;item.isActive&quot; :key=&quot;item.id&quot;&gt; {{ item.name }} &lt;/li&gt; &lt;/ul&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { items: [ { id: 1, name: &#39;Item 1&#39;, isActive: true }, { id: 2, name: &#39;Item 2&#39;, isActive: false }, // 更多项... ] }; } }; &lt;/script&gt;</p><p>优先级解释 在 Vue 2 和 Vue 3 中，<code>v-for</code> 都先于 <code>v-if</code> 解析。解析的顺序是这样的：</p><ol><li><strong><code>v-for</code> 优先</strong>：首先解析 <code>v-for</code>，将每一项渲染成独立的虚拟 DOM 节点。</li><li><strong><code>v-if</code> 次之</strong>：然后在每个独立的虚拟 DOM 节点上应用 <code>v-if</code>，决定是否渲染该节点。 避免混用的推荐方式 正如之前所建议的，避免在同一个元素上同时使用 <code>v-if</code> 和 <code>v-for</code> 可以提高性能和代码可读性。你可以通过以下方式优化： #使用计算属性进行过滤 &lt;template&gt; &lt;ul&gt; &lt;li v-for=&quot;item in filteredItems&quot; :key=&quot;item.id&quot;&gt; {{ item.name }} &lt;/li&gt; &lt;/ul&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { items: [ { id: 1, name: &#39;Item 1&#39;, isActive: true }, { id: 2, name: &#39;Item 2&#39;, isActive: false }, // 更多项... ] }; }, computed: { filteredItems() { return this.items.filter(item =&gt; item.isActive); } } }; &lt;/script&gt; 这样可以避免在模板中进行不必要的条件判断，提高代码的可读性和性能。</li></ol></div>',1)])])}const n=t(d,[["render",f]]);export{m as __pageData,n as default};
